import com.pp.shaderlod.engine.OptimizationRegistry;
import com.pp.shaderlod.domain.PackIdentity;
import java.util.List;
import java.util.Map;
public final class ModuleVerifier {
  public static void main(String[] args) {
    var registry = OptimizationRegistry.load(ModuleVerifier.class.getClassLoader());
    if (args.length == 0) {
      if (!registry.ids().isEmpty()) { throw new AssertionError("Removed provider remains discoverable"); }
      return;
    }
    if (!registry.ids().equals(List.of("module-smoke"))) { throw new AssertionError("Packaged provider absent"); }
    var valid = new PackIdentity("fed6c879e732cf7fc7bc6570ebb1def43235aa7e96f62859fbdbdbfa0b484b38", Map.of());
    if (!registry.prepare(valid, List.of("module-smoke"), Map.of()).isEmpty()) { throw new AssertionError("Identity fixture changed source"); }
    try {
      registry.prepare(new PackIdentity("0".repeat(64), Map.of()), List.of("module-smoke"), Map.of());
    } catch (IllegalArgumentException expected) { return; }
    throw new AssertionError("Unsupported input accepted");
  }
}

